def remplir_cin_normalise(apps, schema_editor):
    """Clé de rapprochement CIN des candidats déjà importés (KAN-42, Q3 bis révisée)."""
    from apps.recruitment.normalization import normalize_cin

    Candidat = apps.get_model("recruitment", "Candidat")
    lot = []
    for c in Candidat.objects.exclude(cin="").only("id", "cin").iterator(chunk_size=2000):
        c.cin_normalise = normalize_cin(c.cin)
        lot.append(c)
        if len(lot) >= 2000:
            Candidat.objects.bulk_update(lot, ["cin_normalise"])
            lot = []
    if lot:
        Candidat.objects.bulk_update(lot, ["cin_normalise"])


